import React, {useState} from 'react';
import '../../App.css';
import './ProjectCard.css';
import CustomCursor from '../CustomCursor/CustomCursor.js';


import { NavLink } from 'react-router-dom';

import PopUp from '../PopUp/PopUp'

import gif from '../../media/peek.gif'
import catPeek from '../../media/peek.png'
import Fade from 'react-reveal/Fade';


function ProjectCard({logo, logoHover, imgHover, title, description, tags}) {

    const [hovered, setHovered] = useState(false);

    return (
        <>  
            <div 
                className="hover-target bordered-section flex-item" 
                style={{
                    backgroundImage: hovered ? `url(${imgHover})` : 'none',
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    color: hovered ? `var(--white)` : `var(--black)`
                }}
                onMouseEnter={() => setHovered(true)}
                onMouseLeave={() => setHovered(false)}>
                <div>
                    <img
                        src={hovered ? logoHover : logo}
                        className="logo" 
                        alt={`{props.title} logo`}
                    />
                    <h2>{title}</h2>
                    <h3>{description}</h3>
                </div>
                <p style={{marginTop: "auto", marginBottom: "0"}}>
                    {tags.map((tag, i) => (
                        <React.Fragment key={i}>
                        {tag}
                        <br />
                        </React.Fragment>
                    ))}
                </p>
            </div>
            {/* <CustomCursor /> */}
        </>
    );
}

export default ProjectCard;
